use std::path::{Path, PathBuf};
use std::process::ExitCode;

mod args;
mod printer;

use args::{parse_args, BatArgs, CompletionShell, NonprintableNotation, ParsedCommand, Stream};
use printer::print_streams;

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let prog = program_name(&argv[0]);

    let raw: Vec<String> = argv.iter().skip(1).cloned().collect();

    // Handle `cache` subcommand before main parsing since it has its own parser.
    if let Some(first) = raw.first() {
        if first == "cache" {
            return run_cache_subcommand(&prog, &raw[1..]);
        }
