fn run_main(args: BatArgs, prog: &str) -> ExitCode {
    // If --quiet-empty is set and all inputs are empty, exit 0 with no output.
    // Implementation: collect data from all streams; if nothing, produce nothing.
    // Otherwise, emit concatenated.
    match print_streams(&args) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            bat_error(&e);
            ExitCode::from(1)
        }
    }
}

