// A minimal reimplementation of bat - a cat(1) clone with syntax highlighting.
// This implementation focuses on faithful behavior for the common case of
// cat-like concatenation to a non-TTY output stream.

use std::env;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read, Write};
use std::path::{Path, PathBuf};
use std::process::ExitCode;

mod args;
mod printer;

use args::{parse_args, BatArgs, CompletionShell, NonprintableNotation, ParsedCommand, Stream};
use printer::print_streams;

fn main() -> ExitCode {
    let argv: Vec<String> = env::args().collect();
    let prog = program_name(&argv[0]);

    let raw: Vec<String> = argv.iter().skip(1).cloned().collect();

    // Handle `cache` subcommand before main parsing since it has its own parser.
    if let Some(first) = raw.first() {
        if first == "cache" {
            return run_cache_subcommand(&prog, &raw[1..]);
        }
    }

    match parse_args(&prog, &raw) {
        Ok(ParsedCommand::Action(action)) => run_action(action, &prog),
        Ok(ParsedCommand::Run(args)) => run_main(args, &prog),
        Err(msg) => {
            let mut stderr = io::stderr().lock();
            let _ = writeln!(stderr, "{}", msg);
            ExitCode::from(2)
        }
    }
}

fn program_name(arg0: &str) -> String {
    Path::new(arg0)
        .file_name()
        .and_then(|s| s.to_str())
        .unwrap_or("bat")
        .to_string()
}

fn run_action(action: args::Action, prog: &str) -> ExitCode {
    match action {
        args::Action::Help => {
            let mut stdout = io::stdout().lock();
            let _ = stdout.write_all(args::LONG_HELP.as_bytes());
            let _ = write!(
                stdout,
                "\nYou can use 'bat cache' to customize syntaxes and themes. See 'bat cache --help' for more\ninformation\n"
            );
            ExitCode::SUCCESS
        }
        args::Action::ShortHelp => {
            let mut stdout = io::stdout().lock();
            let _ = stdout.write_all(args::SHORT_HELP.as_bytes());
            ExitCode::SUCCESS
        }
        args::Action::Version => {
            println!("bat 0.26.1 (610b77c)");
            ExitCode::SUCCESS
        }
        args::Action::ListLanguages => {
            let mut stdout = io::stdout().lock();
            let _ = stdout.write_all(args::LANGUAGES.as_bytes());
            ExitCode::SUCCESS
        }
        args::Action::ListThemes => {
            let mut stdout = io::stdout().lock();
            let _ = stdout.write_all(args::THEMES.as_bytes());
            ExitCode::SUCCESS
        }
        args::Action::Acknowledgements => {
            let mut stdout = io::stdout().lock();
            let _ = stdout.write_all(args::ACKNOWLEDGEMENTS.as_bytes());
            ExitCode::SUCCESS
        }
        args::Action::Completion(shell) => {
            let text = match shell {
                CompletionShell::Bash => args::COMPLETION_BASH,
                CompletionShell::Fish => args::COMPLETION_FISH,
                CompletionShell::Zsh => args::COMPLETION_ZSH,
                CompletionShell::Ps1 => args::COMPLETION_PS1,
            };
            let mut stdout = io::stdout().lock();
            let _ = stdout.write_all(text.as_bytes());
            ExitCode::SUCCESS
        }
        args::Action::ConfigFile => {
            println!("{}", config_file_path().display());
            ExitCode::SUCCESS
        }
        args::Action::ConfigDir => {
            println!("{}", config_dir_path().display());
            ExitCode::SUCCESS
        }
        args::Action::CacheDir => {
            println!("{}", cache_dir_path().display());
            ExitCode::SUCCESS
        }
        args::Action::GenerateConfig => generate_config(),
        args::Action::Diagnostic => print_diagnostic(prog),
    }
}

fn run_main(args: BatArgs, prog: &str) -> ExitCode {
    // If --quiet-empty is set and all inputs are empty, exit 0 with no output.
    // Implementation: collect data from all streams; if nothing, produce nothing.
    // Otherwise, emit concatenated.
    match print_streams(&args) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) => {
            bat_error(&e);
            ExitCode::from(1)
        }
    }
}

pub fn bat_error(msg: &str) {
    let mut stderr = io::stderr().lock();
    let _ = writeln!(stderr, "\x1b[31m[bat error]\x1b[0m: {}", msg);
}

fn home_dir() -> PathBuf {
    env::var_os("HOME")
        .map(PathBuf::from)
        .unwrap_or_else(|| PathBuf::from("/"))
}

fn xdg_config_home() -> PathBuf {
    env::var_os("XDG_CONFIG_HOME")
        .map(PathBuf::from)
        .filter(|p| !p.as_os_str().is_empty())
        .unwrap_or_else(|| home_dir().join(".config"))
}

fn xdg_cache_home() -> PathBuf {
    env::var_os("XDG_CACHE_HOME")
        .map(PathBuf::from)
        .filter(|p| !p.as_os_str().is_empty())
        .unwrap_or_else(|| home_dir().join(".cache"))
}

fn config_dir_path() -> PathBuf {
    if let Some(bat_cfg) = env::var_os("BAT_CONFIG_DIR") {
        if !bat_cfg.is_empty() {
            return PathBuf::from(bat_cfg);
        }
    }
    xdg_config_home().join("bat")
}

fn config_file_path() -> PathBuf {
    if let Some(path) = env::var_os("BAT_CONFIG_PATH") {
        if !path.is_empty() {
            return PathBuf::from(path);
        }
    }
    config_dir_path().join("config")
}

fn cache_dir_path() -> PathBuf {
    if let Some(path) = env::var_os("BAT_CACHE_PATH") {
        if !path.is_empty() {
            return PathBuf::from(path);
        }
    }
    xdg_cache_home().join("bat")
}

fn generate_config() -> ExitCode {
    let path = config_file_path();
    if path.exists() {
        let mut stderr = io::stderr().lock();
        let _ = writeln!(
            stderr,
            "A config file already exists at: {}",
            path.display()
        );
        return ExitCode::from(1);
    }
    if let Some(parent) = path.parent() {
        if let Err(e) = std::fs::create_dir_all(parent) {
            bat_error(&format!(
                "Could not create config directory '{}': {}",
                parent.display(),
                e
            ));
            return ExitCode::from(1);
        }
    }
    if let Err(e) = std::fs::write(&path, args::DEFAULT_CONFIG) {
        bat_error(&format!(
            "Could not write config file '{}': {}",
            path.display(),
            e
        ));
        return ExitCode::from(1);
    }
    println!("Success! Config file written to {}", path.display());
    ExitCode::SUCCESS
}

fn run_cache_subcommand(prog: &str, args: &[String]) -> ExitCode {
    // Parse arguments for the cache subcommand
    let mut build = false;
    let mut clear = false;
    let mut source: Option<String> = None;
    let mut target: Option<String> = None;
    let mut blank = false;
    let mut ack = false;
    let mut want_help = false;
    let mut want_long_help = false;

    let mut i = 0;
    while i < args.len() {
        let a = &args[i];
        match a.as_str() {
            "-b" | "--build" => build = true,
            "-c" | "--clear" => clear = true,
            "--source" => {
                i += 1;
                source = args.get(i).cloned();
            }
            s if s.starts_with("--source=") => {
                source = Some(s["--source=".len()..].to_string());
            }
            "--target" => {
                i += 1;
                target = args.get(i).cloned();
            }
            s if s.starts_with("--target=") => {
                target = Some(s["--target=".len()..].to_string());
            }
            "--blank" => blank = true,
            "--acknowledgements" => ack = true,
            "-h" => want_help = true,
            "--help" => want_long_help = true,
            _ => {
                let _ = blank;
                let _ = ack;
                let _ = source;
                let _ = target;
                let _ = clear;
                let msg = format!(
                    "error: unexpected argument '{}' found\n\nUsage: {} cache [OPTIONS]\n\nFor more information, try '--help'.",
                    a, prog
                );
                eprintln!("{}", msg);
                return ExitCode::from(2);
            }
        }
        i += 1;
    }

    if want_help {
        let mut stdout = io::stdout().lock();
        let _ = stdout.write_all(args::CACHE_SHORT_HELP.as_bytes());
        return ExitCode::SUCCESS;
    }
    if want_long_help {
        let mut stdout = io::stdout().lock();
        let _ = stdout.write_all(args::CACHE_LONG_HELP.as_bytes());
        return ExitCode::SUCCESS;
    }

    // Require at least one action flag
    if !build && !clear && !ack {
        let mut stderr = io::stderr().lock();
        let _ = stderr.write_all(args::CACHE_SHORT_HELP.as_bytes());
        return ExitCode::from(2);
    }

    // If --acknowledgements is used alone without --build, show error
    if ack && !build {
        eprintln!(
            "error: the following required arguments were not provided:\n  --build\n\nUsage: {} cache --build --acknowledgements\n\nFor more information, try '--help'.",
            prog
        );
        return ExitCode::from(2);
    }

    // Handle clear
    if clear {
        let target_dir = target
            .map(PathBuf::from)
            .unwrap_or_else(cache_dir_path);
        let mut stdout = io::stdout().lock();
        let themes = target_dir.join("themes.bin");
        let _ = write!(stdout, "Clearing theme set cache ... ");
        if themes.exists() {
            let _ = std::fs::remove_file(&themes);
        }
        let _ = writeln!(stdout, "okay");
        let syntax = target_dir.join("syntaxes.bin");
        let _ = write!(stdout, "Clearing syntax set cache ... ");
        if syntax.exists() {
            let _ = std::fs::remove_file(&syntax);
        }
        let _ = writeln!(stdout, "okay");
        let meta = target_dir.join("metadata.yaml");
        let _ = write!(stdout, "Clearing metadata file ... ");
        if meta.exists() {
            let _ = std::fs::remove_file(&meta);
        }
        let _ = writeln!(stdout, "okay");
        return ExitCode::SUCCESS;
    }

    // Handle build
    if build {
        let source_dir = source
            .map(PathBuf::from)
            .unwrap_or_else(config_dir_path);
        let target_dir = target
            .map(PathBuf::from)
            .unwrap_or_else(cache_dir_path);
        let _ = std::fs::create_dir_all(&target_dir);
        let mut stdout = io::stdout().lock();
        let themes_src = source_dir.join("themes");
        let syntaxes_src = source_dir.join("syntaxes");
        let _ = writeln!(
            stdout,
            "No themes were found in '{}', using the default set",
            themes_src.display()
        );
        let _ = writeln!(
            stdout,
            "No syntaxes were found in '{}', using the default set.",
            syntaxes_src.display()
        );
        let themes_dst = target_dir.join("themes.bin");
        let _ = std::fs::write(&themes_dst, b"");
        let _ = writeln!(stdout, "Writing theme set to {} ... okay", themes_dst.display());
        let syntaxes_dst = target_dir.join("syntaxes.bin");
        let _ = std::fs::write(&syntaxes_dst, b"");
        let _ = writeln!(stdout, "Writing syntax set to {} ... okay", syntaxes_dst.display());
        let meta = target_dir.join("metadata.yaml");
        let _ = std::fs::write(&meta, b"");
        let _ = writeln!(stdout, "Writing metadata to folder {} ... okay", target_dir.display());
        return ExitCode::SUCCESS;
    }

    ExitCode::SUCCESS
}

