    while i < raw.len() {
        let a = &raw[i];

        if files_after_dash {
            args.files.push(if a == "-" { Stream::Stdin } else { Stream::File(a.clone()) });
            i += 1;
            continue;
        }

        if a == "--" {
            files_after_dash = true;
            i += 1;
            continue;
        }

        if a == "-" {
            args.files.push(Stream::Stdin);
            i += 1;
            continue;
        }

        // Long options with optional =VALUE
        if let Some(rest) = a.strip_prefix("--") {
            let (name, value) = match rest.find('=') {
                Some(p) => (&rest[..p], Some(rest[p + 1..].to_string())),
                None => (rest, None),
