            let need_val = |value: Option<String>, long: &str, possible: Option<&[&str]>| -> Result<String, String> {
                if let Some(v) = value {
                    return Ok(v);
                }
                // Try next arg
                let next = raw.get(i + 1).cloned();
                if let Some(n) = next {
                    Ok(n)
                } else {
                    let possible_str = possible
                        .map(|ps| format!("\n  [possible values: {}]", ps.join(", ")))
                        .unwrap_or_default();
                    Err(format!(
                        "error: a value is required for '--{} <VALUE>' but none was supplied{}",
                        long, possible_str
                    ))
                }
