            let ate_extra = value.is_none();
            let take_val = |val: Option<String>,
                            long: &str,
                            extra: &mut bool,
                            possible: Option<&[&str]>|
             -> Result<String, String> {
                if let Some(v) = val {
                    *extra = false;
                    Ok(v)
                } else {
                    match raw.get(i + 1).cloned() {
                        Some(n) => {
                            *extra = true;
                            Ok(n)
                        }
                        None => {
                            *extra = false;
                            let possible_str = possible
                                .map(|ps| format!("\n  [possible values: {}]", ps.join(", ")))
                                .unwrap_or_default();
                            Err(format!(
                                "error: a value is required for '--{} <VALUE>' but none was supplied{}",
                                long, possible_str
                            ))
                        }
