            let mut j = 0;
            let mut consumed_extra = false;
            while j < chars.len() {
                let c = chars[j];
                match c {
                    'A' => args.show_all = true,
                    'p' => args.plain_count += 1,
                    'n' => args.number = true,
                    'd' => args.diff = true,
                    'S' => { args.chop_long_lines = true; args.wrap = Some(WrapMode::Never); }
                    'f' => { args.force_colorization = true; args.color = Some(WhenTri::Always); args.decorations = Some(WhenTri::Always); }
                    's' => args.squeeze_blank = true,
                    'u' => args.unbuffered = true,
                    'E' => args.quiet_empty = true,
                    'P' => args.paging = Some(WhenTri::Never),
                    'h' => { action = action.or(Some(Action::ShortHelp)); }
                    'V' => { action = action.or(Some(Action::Version)); }
                    'L' => { action = action.or(Some(Action::ListLanguages)); }
                    'l' | 'H' | 'r' | 'm' => {
                        // take value
                        let tail: String = chars[j + 1..].iter().collect();
                        let v = if !tail.is_empty() {
                            tail
                        } else {
                            consumed_extra = true;
                            match raw.get(i + 1).cloned() {
                                Some(x) => x,
                                None => {
                                    return Err(format!(
                                        "error: a value is required for '-{} <VALUE>' but none was supplied",
                                        c
                                    ));
                                }
                            }
                        };
                        match c {
                            'l' => args.language = Some(v),
                            'H' => args.highlight_lines.push(v),
                            'r' => args.line_range.push(v),
                            'm' => args.map_syntax.push(v),
                            _ => unreachable!(),
                        }
                        j = chars.len(); // done for this cluster
                        break;
                    }
                    other => {
                        return Err(format!(
                            "error: unexpected argument '-{}' found\n\n  tip: to pass '-{}' as a value, use '-- -{}'\n\nUsage: {p} [OPTIONS] [FILE]...\n       {p} <COMMAND>",
                            other, other, other, p = prog
                        ));
                    }
                }
                j += 1;
            }
            if consumed_extra {
                i += 2;
            } else {
                i += 1;
            }
            continue;
        }

        // Positional: file
        args.files.push(Stream::File(a.clone()));
        i += 1;
    }

    if let Some(a) = action {
        return Ok(ParsedCommand::Action(a));
    }

    Ok(ParsedCommand::Run(args))
}

fn parse_tri(_flag: &str, v: &str, _label: &str) -> Result<WhenTri, String> {
    match v {
        "auto" => Ok(WhenTri::Auto),
        "never" => Ok(WhenTri::Never),
        "always" => Ok(WhenTri::Always),
        other => Err(format!(
            "error: invalid value '{}' for '--{} <{}>'\n  [possible values: auto, never, always]",
            other, _flag, _label
        )),
    }
}

fn validate_style(v: &str) -> Result<(), String> {
    let known = [
        "default", "full", "auto", "plain",
        "changes", "header", "header-filename", "header-filesize",
        "grid", "rule", "numbers", "snip",
    ];
    for part in v.split(',') {
        if part.is_empty() { continue; }
        let bare = part.trim_start_matches(|c| c == '+' || c == '-');
        if !known.iter().any(|k| *k == bare) {
            return Err(format!(
                "error: invalid value '{}' for '--style <components>': Unknown style '{}'",
                v, bare
            ));
        }
    }
    Ok(())
}
