fn parse_tri(_flag: &str, v: &str, _label: &str) -> Result<WhenTri, String> {
    match v {
        "auto" => Ok(WhenTri::Auto),
        "never" => Ok(WhenTri::Never),
        "always" => Ok(WhenTri::Always),
        other => Err(format!(
            "error: invalid value '{}' for '--{} <{}>'\n  [possible values: auto, never, always]",
            other, _flag, _label
        )),
    }
}

fn validate_style(v: &str) -> Result<(), String> {
    let known = [
        "default", "full", "auto", "plain",
        "changes", "header", "header-filename", "header-filesize",
        "grid", "rule", "numbers", "snip",
    ];
    for part in v.split(',') {
        if part.is_empty() { continue; }
        let bare = part.trim_start_matches(|c| c == '+' || c == '-');
        if !known.iter().any(|k| *k == bare) {
            return Err(format!(
                "error: invalid value '{}' for '--style <components>': Unknown style '{}'",
                v, bare
            ));
        }
    }
    Ok(())
}
