// Printer module - handles reading input streams and writing them to stdout.

use std::fs::File;
use std::io::{self, BufRead, BufReader, Read, Write};
use crate::args::{BatArgs, NonprintableNotation, Stream};

pub fn print_streams(args: &BatArgs) -> Result<(), String> {
    // Determine inputs: if none, read from stdin.
    let streams: Vec<Stream> = if args.files.is_empty() {
        vec![Stream::Stdin]
    } else {
        args.files.clone()
    };

    // For --quiet-empty, collect everything first. Otherwise stream.
    let notation = args.nonprintable_notation.unwrap_or(NonprintableNotation::Unicode);
    let tab_width: Option<u32> = if args.show_all {
        Some(args.tabs.unwrap_or(4))
    } else if let Some(t) = args.tabs {
        if t == 0 { None } else { Some(t) }
    } else {
        None
    };

    let squeeze = args.squeeze_blank;
    let squeeze_limit = args.squeeze_limit.unwrap_or(1) as usize;

    let use_line_range = !args.line_range.is_empty();
    let ranges = parse_line_ranges(&args.line_range)?;

    if args.quiet_empty {
        // Collect entire concatenated content first
        let mut buf: Vec<u8> = Vec::new();
        for s in &streams {
            read_all(s, &mut buf).map_err(|e| format_stream_err(s, &e))?;
        }
        if buf.is_empty() {
            return Ok(());
        }
        let stdout = io::stdout();
        let mut out = stdout.lock();
        process_bytes(&buf, &mut out, args.show_all, notation, tab_width, squeeze, squeeze_limit, use_line_range, &ranges)
            .map_err(|e| e.to_string())?;
        return Ok(());
    }

    let stdout = io::stdout();
    let mut out = stdout.lock();

    let mut had_error: Option<String> = None;
    let mut current_line: u32 = 0;
    let mut blank_run: usize = 0;

    for s in &streams {
        let mut reader: Box<dyn BufRead> = match s {
            Stream::Stdin => Box::new(BufReader::new(io::stdin())),
            Stream::File(path) => match File::open(path) {
                Ok(f) => Box::new(BufReader::new(f)),
                Err(e) => {
                    had_error = Some(format!("'{}': {} (os error {})",
                        path, e_to_msg(&e), e.raw_os_error().unwrap_or(0)));
                    break;
                }
            },
        };
        // Reset state per file? Actually bat treats line numbers per file (style), but
        // for cat-like concatenation we just emit content. Squeeze spans files.
        // Line range applies per file
        let mut file_line: u32 = 0;
        let mut buf = Vec::with_capacity(8192);
        loop {
            buf.clear();
            let n = match reader.read_until(b'\n', &mut buf) {
                Ok(0) => break,
                Ok(n) => n,
                Err(e) => {
                    had_error = Some(format!("read error: {}", e));
                    break;
                }
            };
            let _ = n;
            file_line += 1;
            current_line += 1;

            // Line range check
            if use_line_range && !line_in_ranges(file_line, &ranges) {
                continue;
            }

            // Detect blank line (just "\n" or empty)
            let is_blank = buf == b"\n" || buf.is_empty();
            if squeeze && is_blank {
                blank_run += 1;
                if blank_run > squeeze_limit {
                    continue;
                }
            } else {
                blank_run = 0;
            }

            if let Err(e) = write_line_bytes(
                &buf,
                &mut out,
                args.show_all,
                notation,
                tab_width,
            ) {
                if e.kind() == io::ErrorKind::BrokenPipe {
                    return Ok(());
                }
                had_error = Some(format!("write error: {}", e));
                break;
            }
        }
        if had_error.is_some() {
            break;
        }
    }

    let _ = out.flush();

    if let Some(e) = had_error {
        return Err(e);
    }
    Ok(())
}

fn read_all(s: &Stream, buf: &mut Vec<u8>) -> io::Result<()> {
    match s {
        Stream::Stdin => {
            io::stdin().lock().read_to_end(buf)?;
        }
        Stream::File(path) => {
            let mut f = File::open(path)?;
            f.read_to_end(buf)?;
        }
    }
    Ok(())
}

fn format_stream_err(s: &Stream, err: &io::Error) -> String {
    match s {
        Stream::Stdin => format!("read stdin: {}", err),
        Stream::File(p) => format!(
            "'{}': {} (os error {})",
            p,
            e_to_msg(err),
            err.raw_os_error().unwrap_or(0)
        ),
    }
}

fn e_to_msg(err: &io::Error) -> String {
    // Mirror Rust's default Display for common NotFound => "No such file or directory"
    match err.kind() {
        io::ErrorKind::NotFound => "No such file or directory".to_string(),
        io::ErrorKind::PermissionDenied => "Permission denied".to_string(),
        io::ErrorKind::IsADirectory => "Is a directory".to_string(),
        _ => format!("{}", err),
    }
}

fn process_bytes(
    buf: &[u8],
    out: &mut dyn Write,
    show_all: bool,
    notation: NonprintableNotation,
    tab_width: Option<u32>,
    squeeze: bool,
    squeeze_limit: usize,
    use_line_range: bool,
    ranges: &[(u32, u32)],
) -> io::Result<()> {
    let mut line_start = 0usize;
    let mut line_no: u32 = 0;
    let mut blank_run = 0usize;
    for i in 0..=buf.len() {
        if i == buf.len() || buf[i] == b'\n' {
            let mut end = i;
            if i < buf.len() { end = i + 1; } // include newline
            let line = &buf[line_start..end];
            line_no += 1;

            if use_line_range && !line_in_ranges(line_no, ranges) {
                line_start = end;
                if i == buf.len() && end == buf.len() { break; }
                continue;
            }

            let is_blank = line == b"\n" || line.is_empty();
            if squeeze && is_blank {
                blank_run += 1;
                if blank_run > squeeze_limit {
                    line_start = end;
                    if i == buf.len() && end == buf.len() { break; }
                    continue;
                }
            } else {
                blank_run = 0;
            }

            write_line_bytes(line, out, show_all, notation, tab_width)?;
            line_start = end;
            if i == buf.len() && end == buf.len() { break; }
        }
    }
    Ok(())
}

fn write_line_bytes(
    line: &[u8],
    out: &mut dyn Write,
    show_all: bool,
    notation: NonprintableNotation,
    tab_width: Option<u32>,
) -> io::Result<()> {
    if !show_all && tab_width.is_none() {
        // Fast path: just write as-is
        return out.write_all(line);
    }
    if show_all {
        write_show_all(line, out, notation, tab_width.unwrap_or(4))
    } else {
        // Just expand tabs to spaces
        let n = tab_width.unwrap_or(0) as usize;
        if n == 0 {
            return out.write_all(line);
        }
        let mut col = 0usize;
        let mut tmp = [0u8; 4];
        let s = String::from_utf8_lossy(line);
        for ch in s.chars() {
            if ch == '\t' {
                let spaces = n - (col % n);
                for _ in 0..spaces {
                    out.write_all(b" ")?;
                }
                col += spaces;
            } else if ch == '\n' {
                out.write_all(b"\n")?;
                col = 0;
            } else {
                let s = ch.encode_utf8(&mut tmp);
                out.write_all(s.as_bytes())?;
                col += display_width(ch);
            }
        }
        Ok(())
    }
}

fn write_show_all(
    line: &[u8],
    out: &mut dyn Write,
    notation: NonprintableNotation,
    tab_width: u32,
) -> io::Result<()> {
    let s = String::from_utf8_lossy(line);
    let mut col = 0usize;
    for ch in s.chars() {
        match ch {
            '\t' => {
                let tw = tab_width as usize;
                if tw == 0 {
                    // No expansion, but show the tab marker? Actually use ├─┤ or ^I
                    write_tab_marker(out, notation)?;
                } else {
                    let needed = tw - (col % tw);
                    write_tab_expansion(out, notation, needed)?;
                    col += needed;
                    continue;
                }
            }
            '\n' => {
                // Emit notation for newline then actual newline
                match notation {
                    NonprintableNotation::Unicode => out.write_all("␊".as_bytes())?,
                    NonprintableNotation::Caret => out.write_all(b"^J")?,
                }
                out.write_all(b"\n")?;
                col = 0;
            }
            c if (c as u32) < 0x20 => {
                match notation {
                    NonprintableNotation::Unicode => {
                        // Unicode control pictures U+2400..U+241F
                        let cp = 0x2400 + (c as u32);
                        let mut b = [0u8; 4];
                        let s = char::from_u32(cp).unwrap().encode_utf8(&mut b);
                        out.write_all(s.as_bytes())?;
                        col += 1;
                    }
                    NonprintableNotation::Caret => {
                        let letter = (b'@' + (c as u8)) as char;
                        let mut b = [0u8; 4];
                        let s = letter.encode_utf8(&mut b);
                        out.write_all(b"^")?;
                        out.write_all(s.as_bytes())?;
                        col += 2;
                    }
                }
            }
            c if (c as u32) == 0x7f => {
                match notation {
                    NonprintableNotation::Unicode => {
                        out.write_all("␡".as_bytes())?;
                        col += 1;
                    }
                    NonprintableNotation::Caret => {
                        out.write_all(b"^?")?;
                        col += 2;
                    }
                }
            }
            c => {
                let mut b = [0u8; 4];
                let s = c.encode_utf8(&mut b);
                // Bytes >= 0x80 that are invalid UTF-8 come out as U+FFFD; handle raw later
                out.write_all(s.as_bytes())?;
                col += display_width(c);
            }
        }
    }
    Ok(())
}

fn write_tab_marker(out: &mut dyn Write, notation: NonprintableNotation) -> io::Result<()> {
    match notation {
        NonprintableNotation::Unicode => out.write_all("├─┤".as_bytes()),
        NonprintableNotation::Caret => out.write_all(b"^I"),
    }
}

fn write_tab_expansion(out: &mut dyn Write, notation: NonprintableNotation, needed: usize) -> io::Result<()> {
    // Pattern: ├ then (needed-2) '─' chars then ┤
    // E.g. for needed=3: ├─┤
    // For needed=4: ├──┤
    // For needed=2: ├┤
    // For needed=1: ? (probably just ┤ or similar)
    match notation {
        NonprintableNotation::Unicode => {
            if needed == 0 {
                return Ok(());
            }
            if needed == 1 {
                return out.write_all("─".as_bytes());
            }
            out.write_all("├".as_bytes())?;
            for _ in 0..(needed.saturating_sub(2)) {
                out.write_all("─".as_bytes())?;
            }
            out.write_all("┤".as_bytes())?;
            Ok(())
        }
        NonprintableNotation::Caret => {
            if needed == 0 {
                return Ok(());
            }
            out.write_all(b"^I")?;
            for _ in 0..needed.saturating_sub(2) {
                out.write_all(b" ")?;
            }
            Ok(())
        }
    }
}

fn display_width(c: char) -> usize {
    // Simplified: each non-control char is one column
    // except wide ones (CJK, emoji) but we don't need that precision for cat mode
    if (c as u32) < 0x20 {
        0
    } else {
        1
    }
}

fn parse_line_ranges(specs: &[String]) -> Result<Vec<(u32, u32)>, String> {
    let mut out = Vec::new();
    for s in specs {
        out.push(parse_line_range(s)?);
    }
    Ok(out)
}

fn parse_line_range(spec: &str) -> Result<(u32, u32), String> {
    if spec.is_empty() {
        return Err("Empty line range".to_string());
    }
    // Simple: N, N:M, :M, N:, N:+M
    if let Some(pos) = spec.find(':') {
        let (a, b) = (spec[..pos].trim(), spec[pos + 1..].trim());
        let start = if a.is_empty() { 1 } else { parse_u32(a)? };
        if b.is_empty() {
            return Ok((start, u32::MAX));
        }
        if let Some(stripped) = b.strip_prefix('+') {
            let off = parse_u32(stripped)?;
            return Ok((start, start.saturating_add(off)));
        }
        let end = parse_u32(b)?;
        Ok((start, end))
    } else {
        let n = parse_u32(spec)?;
        Ok((n, n))
    }
}

fn parse_u32(s: &str) -> Result<u32, String> {
    match s.parse::<u32>() {
        Ok(n) => Ok(n),
        Err(_) => Err("invalid digit found in string".to_string()),
    }
}

fn line_in_ranges(line: u32, ranges: &[(u32, u32)]) -> bool {
    ranges.iter().any(|(a, b)| line >= *a && line <= *b)
}
