                        out.write_all(b"^")?;
                        out.write_all(s.as_bytes())?;
                        col += 2;
                    }
                }
            }
            c if (c as u32) == 0x7f => {
                match notation {
                    NonprintableNotation::Unicode => {
                        out.write_all("␡".as_bytes())?;
                        col += 1;
                    }
                    NonprintableNotation::Caret => {
                        out.write_all(b"^?")?;
                        col += 2;
                    }
                }
            }
