fn utf8_len(b: u8) -> usize {
    if b & 0x80 == 0 { 1 }
    else if b & 0xE0 == 0xC0 { 2 }
    else if b & 0xF0 == 0xE0 { 3 }
    else if b & 0xF8 == 0xF0 { 4 }
    else { 0 }
}

fn write_tab_marker(out: &mut dyn Write, notation: NonprintableNotation) -> io::Result<()> {
    match notation {
        NonprintableNotation::Unicode => out.write_all("├─┤".as_bytes()),
        NonprintableNotation::Caret => out.write_all(b"^I"),
    }
}

fn write_tab_expansion(
    out: &mut dyn Write,
    notation: NonprintableNotation,
    needed: usize,
) -> io::Result<()> {
    match notation {
        NonprintableNotation::Unicode => {
            if needed == 0 { return Ok(()); }
            if needed == 1 {
                return out.write_all("─".as_bytes());
            }
            out.write_all("├".as_bytes())?;
            for _ in 0..needed.saturating_sub(2) {
                out.write_all("─".as_bytes())?;
            }
            out.write_all("┤".as_bytes())?;
            Ok(())
        }
        NonprintableNotation::Caret => {
            if needed == 0 { return Ok(()); }
            out.write_all(b"^I")?;
            for _ in 0..needed.saturating_sub(2) {
                out.write_all(b" ")?;
            }
            Ok(())
        }
    }
}

fn display_width(c: char) -> usize {
    if (c as u32) < 0x20 { 0 } else { 1 }
}

fn parse_line_ranges(specs: &[String]) -> Result<Vec<(u32, u32)>, String> {
    let mut out = Vec::new();
    for s in specs {
        out.push(parse_line_range(s)?);
    }
    Ok(out)
}

fn parse_line_range(spec: &str) -> Result<(u32, u32), String> {
    if spec.is_empty() {
        return Err("Empty line range".to_string());
    }
    if let Some(pos) = spec.find(':') {
        let (a, b) = (spec[..pos].trim(), spec[pos + 1..].trim());
        let start = if a.is_empty() { 1 } else { parse_u32(a)? };
        if b.is_empty() {
            return Ok((start, u32::MAX));
        }
        if let Some(stripped) = b.strip_prefix('+') {
            let off = parse_u32(stripped)?;
            return Ok((start, start.saturating_add(off)));
        }
        let end = parse_u32(b)?;
        Ok((start, end))
    } else {
        let n = parse_u32(spec)?;
        Ok((n, n))
    }
}

fn parse_u32(s: &str) -> Result<u32, String> {
    match s.parse::<u32>() {
        Ok(n) => Ok(n),
        Err(_) => Err("invalid digit found in string".to_string()),
    }
}

fn line_in_ranges(line: u32, ranges: &[(u32, u32)]) -> bool {
    ranges.iter().any(|(a, b)| line >= *a && line <= *b)
}
